import {filteredRecords,overview,comparisonPeriod,selectModels} from './domain.js';
export const escapeHtml=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function csvCell(v){const s=String(v??'');const safe=/^[=+@\-\t\r]/.test(s)&&typeof v!=='number'?"'"+s:s;return /[",\n\r]/.test(safe)?`"${safe.replace(/"/g,'""')}"`:safe;}
export const toCsv=rows=>'\uFEFF'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n');
export function exportRows(state,f){return [['Month','Model','Category','Family','Quantity','Activated capacity (kWh)','File','Worksheet','Cell','Original label','Import ID','Last update'],...filteredRecords(state,f).map(r=>{const p=state.catalog[r.model];return [r.month,r.model,p.category,p.family,r.quantity,p.category==='Battery module'?r.quantity*p.capacity:'',r.source.filename,r.source.sheet,r.source.cell,r.source.originalLabel,r.importId,r.updatedAt];})];}
export function summaryRows(state,f){const period=comparisonPeriod(f),a=overview(state,f),b=overview(state,{...f,start:period.start,end:period.end});return [['Metric','Current start','Current end','Comparison start','Comparison end','Current value','Comparison value','Current coverage','Comparison coverage','Category filter','Model filter','Family filter'],...Object.keys(a).map(k=>[k,f.start,f.end,period.start,period.end,a[k].value,b[k].value,a[k].status,b[k].status,f.category,f.model,f.family])];}
export function download(content,name,type='text/plain'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
export function templateRows(dataset,months){const models=dataset==='inverters'?['REPLACE-WITH-INVERTER-MODEL']:['LUNA2000-5-E0','LUNA2000-5-E1','LUNA2000-7-E1','LUNA2000-5KW-C0','LUNA2000-10KW-C1'];return [['index',...months.map(m=>m.replace('-',''))],...models.map(m=>[m,...months.map(()=>'')]),['Total',...months.map(()=>'')]];}
